import json,pathlib,re,collections,hashlib
E=pathlib.Path(__file__).resolve().parent
def load(n):return json.loads((E/n).read_text())
def save(n,x):(E/n).write_text(json.dumps(x,indent=2)+'\n')
def coords(t):return tuple((int(a),int(b)) for a,b in re.findall(r'a\}?_\{([1-4])([1-4])\}',t))
def info(r):
 f=r['question'][':question/answer-fields'][0];bank=[coords(a[':answer/value']) for a in f[':answer-field/choices']];ci=next(i for i,a in enumerate(f[':answer-field/choices']) if a[':answer/id']==f[':answer-field/correct'][1]);return bank,ci
probes=[];coverage=[]
for name,path in [('raw independent','independent-samples.json'),('delivered independent','delivery-independent/accepted.json'),('raw batch','batch-records.json'),('delivered batch','delivery-batch/accepted.json')]:
 rs=load(path);groups={'all':rs,'two-entry sets':[r for r in rs if len(info(r)[0][info(r)[1]])==2],'three-entry sets':[r for r in rs if len(info(r)[0][info(r)[1]])==3]}
 for group,rr in groups.items():
  if not rr:continue
  for cue,strat,fn in [('lexicographic coordinates','Choose the lexicographically first coordinate set',lambda bank:min(range(5),key=lambda i:bank[i])),('stored option index','Choose the first stored option (UI subsequently reorders; this is only a serialization probe)',lambda bank:0)]:
   hits=sum(fn(info(r)[0])==info(r)[1] for r in rr)
   probes.append({'cue':cue,'subgroup':name+' / '+group,'scope':'within_template' if group=='all' else 'other_recognizable_subgroup','strategy':strat,'correct':hits,'total':len(rr),'baseline':0.2,'disposition':'not_predictive','conclusion':f'{hits}/{len(rr)} in this bounded sample, compared with uniform five-choice guessing at 0.2. No deterministic answer-producing cue established; small subgroup deviations are not treated as proof of a defect. Stored index is not visible UI position.','sample_refs':[path]})
 coverage.append({'case':name,'sample_refs':[path],'result':str({'count':len(rs),'correct_sets':len({info(r)[0][info(r)[1]] for r in rs}),'correct_counts':dict(collections.Counter(len(info(r)[0][info(r)[1]]) for r in rs)),'creates_zero_rows':sum(sum(all(v==0 for v in row) for row in r['generation']['parameters']['matrix'])<sum(all(v==0 for v in row) for row in [[0 if (i+1,j+1) in info(r)[0][info(r)[1]] else v for j,v in enumerate(row)] for i,row in enumerate(r['generation']['parameters']['matrix'])]) for r in rs)})})
# Faithful single-band selection calculation from inspected Rust; unknown real future IDs explicitly not fabricated.
inv=json.loads((E.parent/'source/inventory.json').read_text());ids=sorted(q[':db/id'] for q in inv['questions']);draws=[]
for n in range(64):
 seed='independent-review-'+str(n);digest=hashlib.sha256(('course-academy/question-selection/v1/'+seed).encode()).digest();u=(int.from_bytes(digest[8:16],'big')>>11)/(2**53);draws.append({'seed':seed,'selected_entity':ids[int(u*len(ids))]})
save('selection-analysis.json',{'source':'engine/rust/question_selection.rs select, seen_before_task','captured_basis':inv['basis'],'captured_candidate_ids':ids,'condition':'Fresh usable captured candidates, configured positive moderate weight; all are moderate, so band draw cancels and uniform within-band uses digest bytes 8..16.','draws':draws,'default_no_weights':'minimum fresh candidate entity; does not itself guarantee profile balance','history':'prior tasks and current prefix excluded by callers; removing all candidates of a case may remove its coverage','new_batch':'All 5 survive delivery and are moderate. Actual future allocated entity IDs, learner history, policy weights and seeds are unavailable; no live-selection frequencies asserted.','limits':'Selection implementation inspected and captured-pool model exercised; future delivered-pool frequencies conditional, not certified.'})
cf=load('counterfactual-results.json')
p={'learner_operation':load('source-analysis.json')['learner_operation'],'fixed_features':[{'feature':'4x4 ordinary integer matrix and five-option single radio field','justification':'All 15 source practice cases share this moderate workload and response shape.'},{'feature':'Unique global minimum required by current package','justification':'NOT source-justified: source asks whether each offered replacement yields echelon form, without global optimization. See nonminimum-case.json.'}],'answer_roles':[{'role':'Entries removed / surviving leading entries','eligible_variation':'Change zero structure and qualifying coordinate set, preserving row-echelon criterion.','observed':'108 catalogue target sets; sampled correct coordinates change and relevant cell counterfactual changes answer.'},{'role':'Correct bank operation and distractors','eligible_variation':'Include already-zero coordinates in invalid distractors; sole valid offered set need not be a global minimum.','observed':'Generator rejects captured q-73149 bank and nonminimum-case.json; bank restrictions are not justified.'}],'coverage':coverage,'counterfactuals':[{'kind':'relevant','change':'Seed 702312: change a33 from 7 to 0; retain four distractor sets and replace now-redundant keyed set.','expected':'Correct response shrinks from a21,a31,a33 to a21,a31; transformed matrix stays REF; prompt and solution reflect changed a33.','observed':'Independent echelon calculation, actual native grade acceptance/rejection, and rendered prompts/solutions checked for before and after.','status':'passed','justification':'Changing zero/nonzero structure can remove a necessary erasure, per lesson leading-entry definition. Bank update is necessary because old correct choice contains the changed now-zero cell.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-results.json','render-cf/rendering.json']},{'kind':'irrelevant','change':'Same before instance: multiply a12=9 by -2.','expected':'Coordinate response and zero/nonzero structure preserved; visible value and worked matrix update.','observed':'Response preserved; grader accepts same coordinate set and rejects distractors. Renderer shows changed magnitude with same key.','status':'passed','justification':'Nonzero magnitude/sign does not alter row-leading column or zero-row order.','sample_refs':['counterfactual-records.json','counterfactual-results.json','grader-results.json','render-cf/rendering.json']}],'shortcut_probes':probes,'delivery':{'stages_examined':['generator catalogue choice and validation','CLI semantic fingerprint rejection of repeated cases','requested moderate filter','shared prepare_records normalization and captured-inventory deduplication','exact batch survival','native learner selection rule inspection and captured-pool single-band calculation','actual UI choice reorder and rendering'],'sample_refs':['sampling-summary.json','cli-records.json','delivery-independent/delivery.json','delivery-batch/delivery.json','selection-analysis.json','render-delivered/rendering.json'],'result':'32/32 independent and 5/5 exact batch records survive filtering. Decision measurements retained separately above. No deterministic shortcut shown by tested lexicographic/index probes. Specification nevertheless changes the source operation to global minimization and suppresses legitimate bank cases; live learner history/weights not captured.'},'limitations':['Finite samples cannot establish absence of every shortcut.','No actual future database entity allocation or learner state is available; learner selection conclusions are conditional.','Rendered UI reorders choices; stored-position probes do not claim to measure displayed position.','Captured inventory contains five non-source optimization prompts; exact current-generator identity replay failed, so affected-inventory.json is empty for certified reproductions, not a verified absence of affected stored content.']}
save('pedagogical-variation.json',p);save('shortcut-results.json',probes)
print(json.dumps({'probes':len(probes),'perfect_probes':[(x['subgroup'],x['cue']) for x in probes if x['correct']==x['total']],'coverage':coverage}))
